// YOUR ORIGINAL LOGIC PRESERVED
if (!msg.payload.device_id || !msg.payload.timestamp) {
    node.warn('Missing required fields');
    return null;
}

let count = context.get('messageCount') || 0;
count++;
context.set('messageCount', count);

msg.enriched = {
    ...msg.payload,
    processed_at: new Date().toISOString(),
    node_red_version: '1.0',
    topic_original: msg.topic,
    data_quality: {
        valid: true,
        latency_ms: Date.now() - (msg.payload.timestamp * 1000)
    }
};

node.status({
    fill: 'green',
    shape: 'dot',
    text: `${msg.payload.device_id} (${count})`
});

return msg;

msg.payload = {
    ...msg.enriched,
    category: 'PLC',
    priority: 'high'
};
msg.topic = 'collector/ingest';
return msg;

msg.payload = {
    ...msg.enriched,
    category: 'Sensor',
    priority: 'medium'
};
msg.topic = 'collector/ingest';
return msg;

// Topic: factory/data/{DeviceID}
// Payload: { is_on, Rpm, PosX, PosY, in_operation }

const topicParts = msg.topic.split('/');
const deviceId = topicParts[2];

// Handle raw buffer data from MQTT
let payload;
if (Buffer.isBuffer(msg.payload)) {
    try {
        let rawString = msg.payload.toString('utf8');
        node.warn('Raw Unreal data received: ' + rawString);
        // Fix malformed JSON: remove commas from numbers, fix decimal points, add missing commas, normalize keys
        rawString = rawString.replace(/(\d+),(\d+)/g, '$1$2'); // Remove commas in numbers
        rawString = rawString.replace(/(\d+(?:\.\d+)?)\./g, '$1.0'); // Fix trailing decimal points
        rawString = rawString.replace(/(\d+(?:\.\d+)?)\s+"/g, '$1,"'); // Add missing comma after number
        rawString = rawString.replace(/true\s+"/g, 'true,"'); // Add missing comma after true
        rawString = rawString.replace(/"In_operation"/g, '"in_operation"'); // Normalize key case
        rawString = rawString.replace(/"PosX"/g, '"posX"'); // Normalize key case
        rawString = rawString.replace(/"PosY"/g, '"posY"'); // Normalize key case
        rawString = rawString.replace(/"Rpm"/g, '"rpm"'); // Normalize key case
        node.warn('Fixed Unreal data: ' + rawString);
        payload = JSON.parse(rawString);
        node.warn('Parsed Unreal JSON: ' + JSON.stringify(payload));
    } catch (e) {
        node.error('Failed to parse Unreal JSON: ' + e.message);
        node.error('Raw data was: ' + msg.payload.toString('utf8'));
        return null;
    }
} else if (typeof msg.payload === 'string') {
    try {
        let rawString = msg.payload;
        // Fix malformed JSON: remove commas from numbers, fix decimal points, add missing commas, normalize keys
        rawString = rawString.replace(/(\d+),(\d+)/g, '$1$2');
        rawString = rawString.replace(/(\d+(?:\.\d+)?)\./g, '$1.0');
        rawString = rawString.replace(/(\d+(?:\.\d+)?)\s+"/g, '$1,"');
        rawString = rawString.replace(/true\s+"/g, 'true,"');
        rawString = rawString.replace(/"In_operation"/g, '"in_operation"');
        rawString = rawString.replace(/"PosX"/g, '"posX"');
        rawString = rawString.replace(/"PosY"/g, '"posY"');
        rawString = rawString.replace(/"Rpm"/g, '"rpm"');
        payload = JSON.parse(rawString);
    } catch (e) {
        node.error('Failed to parse Unreal string JSON: ' + e.message);
        return null;
    }
} else {
    payload = msg.payload;
}

const timestamp = Date.now();

let msgs = [];

// Helper to create msg
function addMsg(type, val, raw) {
    msgs.push({
        component: deviceId,
        dataType: type,
        payload: val,
        timestamp: timestamp,
        raw_payload: raw
    });
}

// 1. RPM Data
if (payload.Rpm !== undefined) addMsg('rpm', payload.Rpm, payload);
if (payload.rpm !== undefined) addMsg('rpm', payload.rpm, payload);

// 2. Position Data - Send as separate X and Y coordinates
if (payload.PosX !== undefined || payload.posX !== undefined) {
    addMsg('position_x', payload.PosX || payload.posX, payload);
}
if (payload.PosY !== undefined || payload.posY !== undefined) {
    addMsg('position_y', payload.PosY || payload.posY, payload);
}

// 3. Status Data
if (payload.is_on !== undefined) {
    addMsg('status', { 
        isReady: payload.is_on, 
        isDone: payload.in_operation || payload.In_operation || false 
    }, payload);
}

// Send each message to all outputs
msgs.forEach(m => {
    node.send([m, m, m]);
});

return null;

// Maps parsed data to Ignition MQTT topics
let msgs = [];
const ts = msg.timestamp;

function tag(path, val) {
    return {
        topic: 'ignition/tag/write',
        payload: { tagPath: path, value: val, quality: 'GOOD', timestamp: ts }
    };
}

const comp = msg.component;

// CONVEYORS
if (comp.includes('Conveyor') || comp.includes('Belt')) {
    if (msg.dataType === 'rpm') {
        let id = comp.includes('1') ? 'Conveyor1' : 'Conveyor2';
        msgs.push(tag(`[default]${id}/RPM`, msg.payload));
    }
}

// PLACER
if (comp.includes('Placer') || comp.includes('Machine')) {
    if (msg.dataType === 'position_x') {
        msgs.push(tag('[default]Placer1/X', msg.payload));
    }
    else if (msg.dataType === 'position_y') {
        msgs.push(tag('[default]Placer1/Y', msg.payload));
    }
    else if (msg.dataType === 'status') {
        msgs.push(tag('[default]Placer1/IsReady', msg.payload.isReady));
    }
}

return [msgs];

// Use same logic as simulator for consistency
const deviceId = `${msg.component}_${msg.dataType}`;

let fields = {};
if (typeof msg.payload === 'object' && msg.payload !== null) fields = msg.payload;
else fields = { value: msg.payload };

msg.payload = {
    device_id: deviceId,
    timestamp: msg.timestamp / 1000,
    type: 'unreal_sensor',
    data: {
        id: deviceId,
        name: `${msg.component} ${msg.dataType}`,
        signal_config: fields
    },
    metadata: {
        source: 'unreal_engine',
        component: msg.component
    }
};

msg.topic = 'collector/ingest';
return msg;

// Writes Unreal Data to Virtual PLC (Modbus Server)
// 0: Conv1 RPM, 2: Conv2 RPM, 4: Placer X, 6: Placer Y

let addr = -1;
const comp = msg.component;

if (comp.includes('1') && (comp.includes('Belt') || comp.includes('Conveyor'))) addr = 0;
else if (comp.includes('2')) addr = 2;
else if (comp.includes('Placer')) {
    if (msg.dataType === 'position_x') addr = 4;
    else if (msg.dataType === 'position_y') addr = 6;
}

if (addr >= 0 && typeof msg.payload === 'number') {
    msg.payload = {
        value: msg.payload,
        register: 'holding',
        address: addr,
        disableMsgOutput: true
    };
    return msg;
}
return null;

// Ignition Tag writes -> Unreal Commands
// Topic: factory/cmd/{DeviceID}

const parts = msg.topic.split('/');
const comp = parts[2];
const tag = parts[3];
let val = msg.payload;
if(val.value !== undefined) val = val.value;

// Map Ignition Name -> Unreal ID
let devId = comp;
if(comp === 'Conveyor1') devId = 'Belt_01';
if(comp === 'Conveyor2') devId = 'Belt_02';
if(comp === 'Machine1') devId = 'Placer_01';

if(tag === 'Running' || tag === 'Start') {
    msg.topic = `factory/cmd/${devId}`;
    msg.payload = { "is_on": !!val };
    return msg;
}
return null;
